contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        require(newOwner != address(0) && newOwner != address(this));
        address ownerBefore = c.owner();
        c.transferOwnership(newOwner);
        address pending = c.pendingOwner();
        c.acceptOwnership();
        address ownerAfter = c.owner();
